$devices = @('NVIDIA Virtual Audio Device (Wave Extensible) (WDM)','NvModuleTracker Device')
foreach ($d in $devices) {
    try {
        Get-PnpDevice -FriendlyName $d -ErrorAction Stop | Enable-PnpDevice -Confirm:$false
        Write-Host "Enabled: $d"
    } catch {
        Write-Host "Not found: $d"
    }
}

try {
    Remove-ItemProperty -Path 'HKCU:\SOFTWARE\NVIDIA Corporation\NVControlPanel2\Client' -Name 'OptInOrOutPreference'
    Write-Host "Removed: OptInOrOutPreference"
} catch {
    Write-Host "Not found: OptInOrOutPreference"
}

$needles = @('NvTmMon','NvTmRep','NvProfile','NvNodeLauncher','NvDriverUpdateCheckDaily','NvBatteryBoostCheckOnLogon','NVIDIA GeForce Experience SelfUpdate')
$tasks = Get-ScheduledTask | Where-Object { $task = $_; $needles | Where-Object { $task.TaskName -like "*$_*" } }
foreach ($t in $tasks) {
    Enable-ScheduledTask -TaskName $t.TaskName
    Write-Host "Enabled task: $($t.TaskName)"
}
